SELECT id, project_id, operator_id, operator_name, action, log_type, detail, create_time
FROM project_logs
WHERE project_id = #{projectId}
ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM project_logs
WHERE project_id = #{projectId}

SELECT id, project_id, operator_id, operator_name, action, log_type, detail, create_time
FROM project_logs
WHERE project_id = #{projectId}
  AND log_type = #{logType}
ORDER BY id ASC

SELECT id, project_id, operator_id, operator_name, action, log_type, detail, create_time
FROM project_logs
WHERE id = #{id}

mapper.update:
UPDATE project_logs
SET log_type = #{logType}
WHERE id = #{id}
